unsigned long long fn_800F61F4(unsigned int hi, unsigned int lo, unsigned int shift)
{
    return ((unsigned long long)(hi << shift) << 32)
         | ((unsigned long long)(lo >> (32 - shift)) << 32)
         | ((unsigned long long)(lo << (shift - 32)) << 32)
         | (lo << shift);
}

